"""B03A: actual generated bytes, explicit settings and atomic recovery."""
import csv
import io
import json
import threading
from zipfile import ZipFile
import pymupdf
import pypdfium2 as pdfium
import pytest
from app.output_processing import process_generated_pdf, content_contract
from app.pdf_ops import ProcessingError
from test_api import upload, wait_for_job
from test_bundle_structure import settings, save, build


def test_processing_generated_files_office_and_preservation(client, auth, matter, make_pdf):
    docs = [upload(client, auth, matter, make_pdf, name=f'input-{i}.pdf', pages=2) for i in range(2)]
    store = client.app.state.store
    prior = build(client, auth, matter)
    original_paths = [store.original_path(d) for d in docs] + [store.working_path(d) for d in docs]
    prior_paths = list((store.exports_root(matter['id']) / prior['id']).iterdir())
    hashes = {p: store.sha256(p) for p in original_paths + prior_paths}
    cfg = settings(client, auth, matter)
    assert cfg['output_marks']['processing_quality'] == 'original'
    assert not cfg['output_marks']['cleanup_metadata']
    cfg['max_pages_per_volume'] = 3
    cfg['output_marks'].update(processing_quality='balanced', cleanup_metadata=True,
        office_docx=True, office_xlsx=True, office_pptx=True, part_extracts_enabled=True,
        numbering_prefix='V{volume} · ', numbering_back_link=True)
    assert save(client, auth, matter, cfg).status_code == 200
    assert save(client, auth, matter, cfg).status_code == 409
    assert store.list_exports(matter['id'])[0]['stale']
    assert settings(client, auth, matter)['output_marks']['office_docx']
    result = build(client, auth, matter)
    folder = store.exports_root(matter['id']) / result['id']
    assert result['output_marks']['processing_quality'] == 'balanced'
    for f in result['files']:
        assert f['bytes'] == (folder / f['name']).stat().st_size
        assert f['sha256'] == store.sha256(folder / f['name'])
    assert len(result['processing']) == 4  # combined, two volumes, Part 1 extract
    for evidence in result['processing']:
        assert evidence['after_bytes'] == (folder / evidence['filename']).stat().st_size
        assert evidence['metadata_cleared']
        assert 'links' in evidence['verified']
        with pymupdf.open(folder / evidence['filename']) as pdf:
            assert not pdf.metadata['creator'] and not pdf.get_xml_metadata()
    with pymupdf.open(folder / 'combined.pdf') as pdf:
        assert len(pdf) == 6
        assert [link['page'] for link in pdf[0].get_links()] == [1]
        assert [link['page'] for link in pdf[3].get_links()] == [4]
        with pdfium.PdfDocument(str(folder/'combined.pdf')) as independent:
            assert independent.get_page_label(5) == 'V2 · 3'
        assert all(1 <= item[2] <= 6 for item in pdf.get_toc())
    rows = list(csv.DictReader(io.StringIO((folder/'index.csv').read_text(encoding='utf-8-sig'))))
    assert [r['combined_start_page'] for r in rows] == ['2', '5']
    assert [r['end_page'] for r in rows] == ['3', '3']
    report = json.loads((folder/'validation-report.json').read_text())
    assert report['combined_bytes'] == (folder/'combined.pdf').stat().st_size
    with ZipFile(folder/'filing-package.zip') as archive:
        for filename in ['combined-review.docx', 'index-review.xlsx', 'combined-review.pptx']:
            assert archive.read(filename) == (folder/filename).read_bytes()
            with ZipFile(folder/filename) as office:
                assert office.testzip() is None
    qa = client.get(f'/matters/{matter["id"]}/exports/{result["id"]}/validation/state', headers=auth).json()
    assert qa['can_download'], json.dumps(qa,indent=2)
    assert all(store.sha256(p) == h for p, h in hashes.items())


@pytest.mark.parametrize('preset', ['original', 'lossless', 'balanced', 'small'])
def test_actual_image_effect_and_navigation(tmp_path, preset):
    path = tmp_path/'generated.pdf'
    # Deterministic photographic-like pixels; lossless source deliberately large.
    import random
    pixels = random.Random(42).randbytes(900*900*3)
    pix = pymupdf.Pixmap(pymupdf.csRGB, 900, 900, pixels, False)
    with pymupdf.open() as pdf:
        p = pdf.new_page()
        p.insert_image(pymupdf.Rect(50, 50, 150, 150), pixmap=pix)
        p.insert_text((50, 200), 'Searchable retained text')
        pdf.new_page()
        pdf[0].insert_link({'kind':pymupdf.LINK_GOTO,'from':pymupdf.Rect(40,190,250,210),'page':1})
        pdf.set_toc([[1,'Destination',2]])
        pdf.set_metadata({'author':'Synthetic private author', 'creator':'Test'})
        pdf.save(path)
    before = content_contract(path)
    original = path.read_bytes()
    result = process_generated_pdf(path, dict(processing_quality=preset), lambda:False)
    assert content_contract(path) == before
    assert result['after_bytes'] == path.stat().st_size
    if preset in ('balanced','small'):
        assert result['compression']['images_rewritten'] == 1
        assert path.stat().st_size < len(original)/2
    if preset == 'original':
        assert path.read_bytes() == original


@pytest.mark.parametrize('mode', ['failure', 'cancel', 'stale'])
def test_failed_processing_keeps_prior_build_and_intended_settings(client, auth, matter, make_pdf, monkeypatch, mode):
    import app.engine as engine
    doc = upload(client, auth, matter, make_pdf)
    store = client.app.state.store
    prior = build(client, auth, matter)
    paths = list((store.exports_root(matter['id'])/prior['id']).iterdir()) + [store.original_path(doc)]
    hashes = {p:store.sha256(p) for p in paths}
    cfg = settings(client,auth,matter);cfg['output_marks']['processing_quality']='small'
    assert save(client,auth,matter,cfg).status_code == 200
    entered, release = threading.Event(), threading.Event()
    actual = engine.process_generated_pdf
    def gated(*args):
        entered.set()
        assert release.wait(10)
        if mode == 'failure':
            raise ProcessingError('Synthetic output processing failure')
        if mode == 'stale':
            store.set_output_marks(matter['id'], {**store.get_output_marks(matter['id']), 'cleanup_metadata':True})
        return actual(*args)
    monkeypatch.setattr(engine,'process_generated_pdf',gated)
    response = client.post(f'/matters/{matter["id"]}/build',headers=auth).json()
    assert entered.wait(10)
    if mode == 'cancel':
        assert client.post(f'/jobs/{response["id"]}/cancel',headers=auth).status_code == 200
    release.set()
    result=wait_for_job(client,auth,response['id'])
    assert result['status'] == ('cancelled' if mode == 'cancel' else 'failed'), result
    assert len(store.list_exports(matter['id'])) == 1
    assert all(store.sha256(p)==h for p,h in hashes.items())
    assert settings(client,auth,matter)['output_marks']['processing_quality']=='small'
    monkeypatch.setattr(engine,'process_generated_pdf',actual)
    build(client,auth,matter)
    assert not list(store.exports_root(matter['id']).glob('.build-*'))


def test_unsupported_processing_settings_reject(client,auth,matter):
    cfg=settings(client,auth,matter)
    cfg['output_marks']['print_layout']='duplex'
    assert save(client,auth,matter,cfg).status_code==422
    cfg['output_marks']['print_layout']='screen'
    cfg['output_marks']['processing_quality']='rasterize'
    assert save(client,auth,matter,cfg).status_code==422


def test_default_processing_preserves_legacy_freshness_digest(client, auth, matter, monkeypatch):
    store = client.app.state.store
    current = store.build_input_digest(matter['id'], effective=True)
    getter = store.get_output_marks
    keys = ('processing_quality','cleanup_metadata','print_layout','office_docx','office_xlsx','office_pptx')
    monkeypatch.setattr(store, 'get_output_marks', lambda mid: {k:v for k,v in getter(mid).items() if k not in keys})
    assert store.build_input_digest(matter['id'], effective=True) == current
